//! Murmur3
//!
//! Module containing 7 functions: rotl32, rotl64, fmix32, fmix64,
//! MurmurHash3_x86_32, MurmurHash3_x86_128, MurmurHash3_x64_128

#![allow(unused_variables, unused_imports, dead_code)]

use crate::*;

/// Rotl32
/// Performs a left circular shift (rotation) on a 32-bit unsigned integer.
pub fn rotl32(x: u32, r: u32) -> u32 {
    let r = r % 32;
    if r == 0 {
        return x;
    }
    (x << r) | (x >> (32 - r))
}

/// Rotl64
/// Performs a circular left rotation (bit-rotate) on a 64-bit unsigned integer.
pub fn rotl64(x: u64, r: u32) -> u64 {
    let r = r % 64;
    if r == 0 {
        return x;
    }
    (x << r) | (x >> (64 - r))
}

/// Fmix32
/// A finalization mix function that forces all bits of a 32-bit hash block to
/// avalanche, ensuring that small changes in the input result in large changes in
/// the output.
///
/// Standards: MurmurHash3
pub fn fmix32(mut h: u32) -> u32 {
    h ^= h >> 16;
    h = h.wrapping_mul(0x85ebca6b);
    h ^= h >> 13;
    h = h.wrapping_mul(0xc2b2ae35);
    h ^= h >> 16;
    h
}

/// Fmix64
/// A finalization mix function that distributes the entropy of a 64-bit hash value
/// to ensure high avalanche effect.
///
/// Standards: MurmurHash3
pub fn fmix64(mut k: u64) -> u64 {
    k ^= k >> 33;
    k = k.wrapping_mul(0xff51afd7ed558ccd);
    k ^= k >> 33;
    k = k.wrapping_mul(0xc4ceb9fe1a85ec53);
    k ^= k >> 33;
    k
}

/// Murmurhash3 X86 32
/// Implements the 32-bit MurmurHash3 algorithm for x86 architectures, providing a
/// fast, non-cryptographic hash of a byte sequence.
///
/// Standards: MurmurHash3 (Austin Appleby)
pub fn murmur_hash3_x86_32(key: &[u8], seed: u32) -> Vec<u8> {
    let len = key.len();
    let nblocks = len / 4;
    let mut h1 = seed;

    let c1: u32 = 0xcc9e2d51;
    let c2: u32 = 0x1b873593;

    for i in 0..nblocks {
        let offset = i * 4;
        let mut k1 = ((key[offset] as u32)
            | ((key[offset + 1] as u32) << 8)
            | ((key[offset + 2] as u32) << 16)
            | ((key[offset + 3] as u32) << 24));

        k1 = k1.wrapping_mul(c1);
        k1 = k1.rotate_left(15);
        k1 = k1.wrapping_mul(c2);

        h1 ^= k1;
        h1 = h1.rotate_left(13);
        h1 = h1.wrapping_mul(5).wrapping_add(0xe6546b64);
    }

    let mut k1: u32 = 0;
    let tail_offset = nblocks * 4;
    let remainder = len & 3;

    if remainder >= 3 {
        k1 ^= (key[tail_offset + 2] as u32) << 16;
    }
    if remainder >= 2 {
        k1 ^= (key[tail_offset + 1] as u32) << 8;
    }
    if remainder >= 1 {
        k1 ^= key[tail_offset] as u32;
        k1 = k1.wrapping_mul(c1);
        k1 = k1.rotate_left(15);
        k1 = k1.wrapping_mul(c2);
        h1 ^= k1;
    }

    h1 ^= len as u32;

    // fmix32
    h1 ^= h1 >> 16;
    h1 = h1.wrapping_mul(0x85ebca6b);
    h1 ^= h1 >> 13;
    h1 = h1.wrapping_mul(0xc2b2ae35);
    h1 ^= h1 >> 16;

    h1.to_le_bytes().to_vec()
}

/// Murmurhash3 X86 128
/// Implements the 128-bit MurmurHash3 algorithm optimized for x86 architectures,
/// producing a high-quality hash from an input byte slice.
///
/// Standards: MurmurHash3 (Austin Appleby)
pub fn murmur_hash3_x86_128(key: &[u8], seed: u32) -> Vec<u8> {
    fn fmix32(mut h: u32) -> u32 {
        h ^= h >> 16;
        h = h.wrapping_mul(0x85ebca6b);
        h ^= h >> 13;
        h = h.wrapping_mul(0xc2b2ae35);
        h ^= h >> 16;
        h
    }

    let len = key.len();
    let nblocks = len / 16;

    let mut h1 = seed;
    let mut h2 = seed;
    let mut h3 = seed;
    let mut h4 = seed;

    let c1: u32 = 0x239b961b;
    let c2: u32 = 0xab0e9789;
    let c3: u32 = 0x38b34ae5;
    let c4: u32 = 0xa1e38b93;

    for i in 0..nblocks {
        let offset = i * 16;
        let k1 = u32::from_le_bytes([key[offset], key[offset + 1], key[offset + 2], key[offset + 3]]);
        let k2 = u32::from_le_bytes([key[offset + 4], key[offset + 5], key[offset + 6], key[offset + 7]]);
        let k3 = u32::from_le_bytes([key[offset + 8], key[offset + 9], key[offset + 10], key[offset + 11]]);
        let k4 = u32::from_le_bytes([key[offset + 12], key[offset + 13], key[offset + 14], key[offset + 15]]);

        let mut k1 = k1.wrapping_mul(c1).rotate_left(15).wrapping_mul(c2);
        h1 ^= k1;
        h1 = h1.rotate_left(19).wrapping_add(h2).wrapping_mul(5).wrapping_add(0x561ccd1b);

        let mut k2 = k2.wrapping_mul(c2).rotate_left(16).wrapping_mul(c3);
        h2 ^= k2;
        h2 = h2.rotate_left(17).wrapping_add(h3).wrapping_mul(5).wrapping_add(0x0bcaa747);

        let mut k3 = k3.wrapping_mul(c3).rotate_left(17).wrapping_mul(c4);
        h3 ^= k3;
        h3 = h3.rotate_left(15).wrapping_add(h4).wrapping_mul(5).wrapping_add(0x96cd1c35);

        let mut k4 = k4.wrapping_mul(c4).rotate_left(18).wrapping_mul(c1);
        h4 ^= k4;
        h4 = h4.rotate_left(13).wrapping_add(h1).wrapping_mul(5).wrapping_add(0x32ac3b17);
    }

    let tail = &key[nblocks * 16..];
    let mut k1 = 0u32;
    let mut k2 = 0u32;
    let mut k3 = 0u32;
    let mut k4 = 0u32;

    let rem = len & 15;
    if rem >= 15 {
        k4 ^= (tail[14] as u32) << 16;
    }
    if rem >= 14 {
        k4 ^= (tail[13] as u32) << 8;
    }
    if rem >= 13 {
        k4 ^= (tail[12] as u32) << 0;
        k4 = k4.wrapping_mul(c4).rotate_left(18).wrapping_mul(c1);
        h4 ^= k4;
    }
    if rem >= 12 {
        k3 ^= (tail[11] as u32) << 24;
    }
    if rem >= 11 {
        k3 ^= (tail[10] as u32) << 16;
    }
    if rem >= 10 {
        k3 ^= (tail[9] as u32) << 8;
    }
    if rem >= 9 {
        k3 ^= (tail[8] as u32) << 0;
        k3 = k3.wrapping_mul(c3).rotate_left(17).wrapping_mul(c4);
        h3 ^= k3;
    }
    if rem >= 8 {
        k2 ^= (tail[7] as u32) << 24;
    }
    if rem >= 7 {
        k2 ^= (tail[6] as u32) << 16;
    }
    if rem >= 6 {
        k2 ^= (tail[5] as u32) << 8;
    }
    if rem >= 5 {
        k2 ^= (tail[4] as u32) << 0;
        k2 = k2.wrapping_mul(c2).rotate_left(16).wrapping_mul(c3);
        h2 ^= k2;
    }
    if rem >= 4 {
        k1 ^= (tail[3] as u32) << 24;
    }
    if rem >= 3 {
        k1 ^= (tail[2] as u32) << 16;
    }
    if rem >= 2 {
        k1 ^= (tail[1] as u32) << 8;
    }
    if rem >= 1 {
        k1 ^= (tail[0] as u32) << 0;
        k1 = k1.wrapping_mul(c1).rotate_left(15).wrapping_mul(c2);
        h1 ^= k1;
    }

    h1 ^= len as u32;
    h2 ^= len as u32;
    h3 ^= len as u32;
    h4 ^= len as u32;

    h1 = h1.wrapping_add(h2).wrapping_add(h3).wrapping_add(h4);
    h2 = h2.wrapping_add(h1);
    h3 = h3.wrapping_add(h1);
    h4 = h4.wrapping_add(h1);

    h1 = fmix32(h1);
    h2 = fmix32(h2);
    h3 = fmix32(h3);
    h4 = fmix32(h4);

    h1 = h1.wrapping_add(h2).wrapping_add(h3).wrapping_add(h4);
    h2 = h2.wrapping_add(h1);
    h3 = h3.wrapping_add(h1);
    h4 = h4.wrapping_add(h1);

    let mut out = Vec::with_capacity(16);
    out.extend_from_slice(&h1.to_le_bytes());
    out.extend_from_slice(&h2.to_le_bytes());
    out.extend_from_slice(&h3.to_le_bytes());
    out.extend_from_slice(&h4.to_le_bytes());
    out
}

/// Murmurhash3 X64 128
/// Implements the 128-bit MurmurHash3 algorithm optimized for 64-bit
/// architectures, producing a high-quality non-cryptographic hash of a byte
/// sequence.
///
/// Standards: MurmurHash3 (Austin Appleby)
pub fn murmur_hash3_x64_128(key: &[u8], seed: u32) -> Vec<u8> {
    fn fmix64(mut k: u64) -> u64 {
        k ^= k >> 33;
        k = k.wrapping_mul(0xff51afd7ed558ccd);
        k ^= k >> 33;
        k = k.wrapping_mul(0xc4ceb9fe1a85ec53);
        k ^= k >> 33;
        k
    }

    let len = key.len();
    let nblocks = len / 16;
    let mut h1 = seed as u64;
    let mut h2 = seed as u64;

    let c1: u64 = 0x87c37b91114253d5;
    let c2: u64 = 0x4cf5ad432745937f;

    for i in 0..nblocks {
        let offset = i * 16;
        let mut k1 = u64::from_le_bytes(key[offset..offset + 8].try_into().unwrap());
        let mut k2 = u64::from_le_bytes(key[offset + 8..offset + 16].try_into().unwrap());

        k1 = k1.wrapping_mul(c1);
        k1 = k1.rotate_left(31);
        k1 = k1.wrapping_mul(c2);
        h1 ^= k1;

        h1 = h1.rotate_left(27);
        h1 = h1.wrapping_add(h2);
        h1 = h1.wrapping_mul(5).wrapping_add(0x52dce729);

        k2 = k2.wrapping_mul(c2);
        k2 = k2.rotate_left(33);
        k2 = k2.wrapping_mul(c1);
        h2 ^= k2;

        h2 = h2.rotate_left(31);
        h2 = h2.wrapping_add(h1);
        h2 = h2.wrapping_mul(5).wrapping_add(0x38495ab5);
    }

    let tail = &key[nblocks * 16..];
    let mut k1: u64 = 0;
    let mut k2: u64 = 0;

    let rem = len & 15;
    if rem >= 9 {
        if rem == 15 { k2 ^= (tail[14] as u64) << 48; }
        if rem >= 14 { k2 ^= (tail[13] as u64) << 40; }
        if rem >= 13 { k2 ^= (tail[12] as u64) << 32; }
        if rem >= 12 { k2 ^= (tail[11] as u64) << 24; }
        if rem >= 11 { k2 ^= (tail[10] as u64) << 16; }
        if rem >= 10 { k2 ^= (tail[9] as u64) << 8; }
        if rem >= 9 { k2 ^= (tail[8] as u64) << 0; }
        k2 = k2.wrapping_mul(c2);
        k2 = k2.rotate_left(33);
        k2 = k2.wrapping_mul(c1);
        h2 ^= k2;
    }
    if rem >= 1 {
        if rem >= 8 { k1 ^= (tail[7] as u64) << 56; }
        if rem >= 7 { k1 ^= (tail[6] as u64) << 48; }
        if rem >= 6 { k1 ^= (tail[5] as u64) << 40; }
        if rem >= 5 { k1 ^= (tail[4] as u64) << 32; }
        if rem >= 4 { k1 ^= (tail[3] as u64) << 24; }
        if rem >= 3 { k1 ^= (tail[2] as u64) << 16; }
        if rem >= 2 { k1 ^= (tail[1] as u64) << 8; }
        if rem >= 1 { k1 ^= (tail[0] as u64) << 0; }
        k1 = k1.wrapping_mul(c1);
        k1 = k1.rotate_left(31);
        k1 = k1.wrapping_mul(c2);
        h1 ^= k1;
    }

    h1 ^= len as u64;
    h2 ^= len as u64;

    h1 = h1.wrapping_add(h2);
    h2 = h2.wrapping_add(h1);

    h1 = fmix64(h1);
    h2 = fmix64(h2);

    h1 = h1.wrapping_add(h2);
    h2 = h2.wrapping_add(h1);

    let mut out = Vec::with_capacity(16);
    out.extend_from_slice(&h1.to_le_bytes());
    out.extend_from_slice(&h2.to_le_bytes());
    out
}

